--
-- Name: auto_assign_investigation_func(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_assign_investigation_func() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_selected_moderator INT;
    v_new_investigation_id INT;
BEGIN
    -- מציאת המודרטור הפנוי ביותר (למי יש הכי פחות חקירות בסטטוס In Progress)
    SELECT m.Moderator_ID INTO v_selected_moderator
    FROM MODERATORS m
    LEFT JOIN INVESTIGATIONS i ON m.Moderator_ID = i.Moderator_ID AND i.Status = 'In Progress'
    GROUP BY m.Moderator_ID
    ORDER BY COUNT(i.Investigation_ID) ASC
    LIMIT 1;

    -- יצירת מזהה חקירה חדש (נמצא את הערך המקסימלי ונוסיף 1)
    SELECT COALESCE(MAX(Investigation_ID), 0) + 1 INTO v_new_investigation_id FROM INVESTIGATIONS;

    -- יצירת החקירה החדשה והקצאתה למודרטור שנבחר
    VALUES (
        v_new_investigation_id, 
        CURRENT_DATE, 
        NULL, 
        'In Progress', 
        v_selected_moderator, 
        NEW.Report_ID
    );

    RAISE NOTICE 'דיווח חדש (%) התקבל. חקירה חדשה (%) נפתחה אוטומטית והוקצתה למודרטור מספר %.', NEW.Report_ID, v_new_investigation_id, v_selected_moderator;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.auto_assign_investigation_func() OWNER TO postgres;

--
-- Name: calculate_moderator_bonus(integer, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_moderator_bonus(p_moderator_id integer, p_year integer, p_month integer) RETURNS numeric
    LANGUAGE plpgsql
    AS $$
DECLARE
    total_bonus NUMERIC := 0.0;
    ban_record RECORD;
    -- הגדרת הסמן (Cursor) לשליפת נתוני החסימות הרלוונטיות
    cur_bans CURSOR FOR 
        SELECT (b.End_Date - b.Start_Date) AS Ban_Duration
        FROM INVESTIGATIONS i
        JOIN BANS b ON i.Investigation_ID = b.Investigation_ID
        WHERE i.Moderator_ID = p_moderator_id
          AND i.Status = 'Closed'
          AND EXTRACT(YEAR FROM i.Closed_Date) = p_year
          AND EXTRACT(MONTH FROM i.Closed_Date) = p_month;
BEGIN
    -- פתיחת הסמן
    OPEN cur_bans;
    
    -- לולאה למעבר על כל שורה בתוצאת הסמן
    LOOP
        FETCH cur_bans INTO ban_record;
        EXIT WHEN NOT FOUND;
        
        -- חישוב הבונוס: 10 שקלים/דולרים על כל יום חסימה שהמודרטור חילק (משקף את חומרת העבירה שהוא איתר)
        total_bonus := total_bonus + (ban_record.Ban_Duration * 10);
    END LOOP;
    
    -- סגירת הסמן
    CLOSE cur_bans;
    
    RETURN total_bonus;
END;
$$;


ALTER FUNCTION public.calculate_moderator_bonus(p_moderator_id integer, p_year integer, p_month integer) OWNER TO postgres;

--
-- Name: close_investigation_and_notify(integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.close_investigation_and_notify(IN p_investigation_id integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_current_status VARCHAR;
BEGIN
    -- קודם נוודא שהחקירה קיימת ושנמצאת במצב פתוח (In Progress)
    SELECT Status INTO v_current_status
    FROM INVESTIGATIONS
    WHERE Investigation_ID = p_investigation_id;

    IF v_current_status IS NULL THEN
        RAISE NOTICE 'חקירה מספר % לא נמצאה.', p_investigation_id;
        RETURN;
    END IF;

    IF v_current_status = 'Closed' THEN
        RAISE NOTICE 'חקירה מספר % כבר סגורה!', p_investigation_id;
        RETURN;
    END IF;

    -- עדכון נתוני החקירה לסגירה
    UPDATE INVESTIGATIONS
    SET Status = 'Closed',
        Closed_Date = CURRENT_DATE
    WHERE Investigation_ID = p_investigation_id;

    -- הודעת מערכת (Log) שמסכמת את הפעולה
    RAISE NOTICE '*** מערכת FairPlay: חקירה מספר % נסגרה בהצלחה בתאריך % ***', p_investigation_id, CURRENT_DATE;
END;
$$;


ALTER PROCEDURE public.close_investigation_and_notify(IN p_investigation_id integer) OWNER TO postgres;

--
-- Name: extend_ban_for_repeat_offenders(integer, integer); Type: PROCEDURE; Schema: public; Owner: postgres
--

CREATE PROCEDURE public.extend_ban_for_repeat_offenders(IN p_ban_id integer, IN p_extra_days integer)
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_ban_exists BOOLEAN;
BEGIN
    -- בדיקה 1: האם מספר הימים הגיוני (חיובי)
    IF p_extra_days <= 0 THEN
        RAISE EXCEPTION 'מספר הימים להארכה חייב להיות גדול מאפס. התקבל: %', p_extra_days;
    END IF;

    -- בדיקה 2: האם החסימה בכלל קיימת במסד הנתונים
    SELECT EXISTS (SELECT 1 FROM BANS WHERE Ban_ID = p_ban_id) INTO v_ban_exists;
    IF NOT v_ban_exists THEN
        RAISE EXCEPTION 'חסימה מספר % לא קיימת במערכת!', p_ban_id;
    END IF;

    -- אם הכל תקין, נבצע את ההארכה של תאריך הסיום
    UPDATE BANS
    SET End_Date = End_Date + p_extra_days
    WHERE Ban_ID = p_ban_id;
    
    RAISE NOTICE 'החסימה מספר % הוארכה בהצלחה ב-% ימים.', p_ban_id, p_extra_days;

EXCEPTION
    -- תפיסת שגיאות והדפסת הודעה יפה למשתמש
    WHEN RAISE_EXCEPTION THEN
        RAISE NOTICE 'שגיאה בהארכת חסימה: %', SQLERRM;
    WHEN OTHERS THEN
        RAISE NOTICE 'אירעה שגיאה לא צפויה: %', SQLERRM;
END;
$$;


ALTER PROCEDURE public.extend_ban_for_repeat_offenders(IN p_ban_id integer, IN p_extra_days integer) OWNER TO postgres;

--
-- Name: is_high_risk_player(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_high_risk_player(p_player_name character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    past_bans_count INT;
    active_reports_count INT;
BEGIN
    -- בדיקת כמות החסימות בעבר
    SELECT COUNT(*) INTO past_bans_count
    FROM BANS
    WHERE Banned_Player = p_player_name;
    
    -- בדיקת כמות הדיווחים התלויים ועומדים נגדו
    SELECT COUNT(*) INTO active_reports_count
    FROM REPORTS r
    JOIN INVESTIGATIONS i ON r.Report_ID = i.Report_ID
    WHERE r.Suspect_name = p_player_name
      AND i.Status IN ('In Progress', 'Pending');
      
    -- אם יש יותר מ-1 חסימה או יותר מ-2 דיווחים פתוחים, הוא בסיכון גבוה
    IF past_bans_count >= 2 OR active_reports_count >= 3 THEN
        RETURN TRUE;
    ELSE
        RETURN FALSE;
    END IF;
END;
$$;


ALTER FUNCTION public.is_high_risk_player(p_player_name character varying) OWNER TO postgres;

--
-- Name: prevent_ban_reduction_func(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prevent_ban_reduction_func() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- בדיקה האם יש ניסיון לקצר את תאריך הסיום
    IF NEW.End_Date < OLD.End_Date THEN
        RAISE EXCEPTION 'מדיניות המערכת אינה מאפשרת קיצור של תאריך סיום חסימה פעילה (Ban_ID: %). התאריך המקורי: %, התאריך שהתבקש: %', 
            NEW.Ban_ID, OLD.End_Date, NEW.End_Date;
    END IF;
    
    -- אם הכל תקין, ממשיכים בפעולת העדכון
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.prevent_ban_reduction_func() OWNER TO postgres;

