--
-- Name: moderation_queue_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.moderation_queue_view AS
 SELECT i.investigation_id,
    i.opened_date,
    i.status,
    m.mname AS moderator_name,
    r.report_id,
    r.reporter_name,
    r.suspect_name,
    r.description AS report_reason,
    g.game_id,
    g.start_date AS game_date
   FROM (((public.investigations i
     JOIN public.moderators m ON ((i.moderator_id = m.moderator_id)))
     JOIN public.reports r ON ((i.report_id = r.report_id)))
     JOIN public.game g ON ((r.game_id = g.game_id)));


