--
-- Name: suspicious_games_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.suspicious_games_view AS
 SELECT g.game_id,
    g.start_date,
    g.result,
    tc.name AS time_control,
    gv.name AS variant,
    count(r.report_id) AS total_reports
   FROM (((public.game g
     JOIN public.reports r ON ((g.game_id = r.game_id)))
     LEFT JOIN public.timecontrol tc ON ((g.tc_id = tc.tc_id)))
     LEFT JOIN public.gamevariant gv ON ((g.variant_id = gv.variant_id)))
  GROUP BY g.game_id, g.start_date, g.result, tc.name, gv.name;


